async function loadFollowedBags(client, followerId) {
const { data: followsData, error: followsErr } = await client
.from("bag_follows")
.select("bag_id, created_at, bags(id, name, user_id, is_private)")
.eq("follower_id", followerId)
.order("created_at", { ascending: true });
if (followsErr) return { error: followsErr };
const bags = {};
const order = [];
const ownerIds = new Set();
(followsData || []).forEach((f) => {
const b = f.bags;
if (!b) return;
bags[b.id] = {
id: b.id,
name: b.name,
ownerId: b.user_id,
ownerName: "a friend",
items: [],
likeCount: 0,
isLiked: false
};
order.push(b.id);
ownerIds.add(b.user_id);
});
if (order.length === 0) return { data: { order, bags } };
const { data: profilesData, error: profilesErr } = await client
.from("profiles")
.select("user_id, display_name")
.in("user_id", Array.from(ownerIds));
if (profilesErr) return { error: profilesErr };
(profilesData || []).forEach((p) => {
if (!p.display_name) return;
order.forEach((bagId) => {
if (bags[bagId].ownerId === p.user_id) bags[bagId].ownerName = p.display_name;
});
});
const { data: itemsData, error: itemsErr } = await client
.from("items")
.select("*")
.in("bag_id", order)
.order("added_at", { ascending: false });
if (itemsErr) return { error: itemsErr };
(itemsData || []).forEach((item) => {
const bag = bags[item.bag_id];
if (!bag) return;
bag.items.push({
id: item.id,
title: item.title,
price: item.price,
originalPrice: item.original_price,
size: item.size,
site: item.site,
image: item.image,
url: item.url,
addedAt: item.added_at
});
});
const { data: likeInfo, error: likeErr } = await fetchLikeInfo(client, order, followerId);
if (likeErr) return { error: likeErr };
order.forEach((bagId) => {
bags[bagId].likeCount = likeInfo.counts[bagId] || 0;
bags[bagId].isLiked = likeInfo.likedSet.has(bagId);
});
return { data: { order, bags } };
}
async function loadSharedBag(client, bagId, viewerId) {
const { data: bag, error: bagErr } = await client
.from("bags")
.select("id, name, user_id, is_private")
.eq("id", bagId)
.maybeSingle();
if (bagErr) return { error: bagErr };
if (!bag) return { data: null };
const { data: profile } = await client
.from("profiles")
.select("display_name")
.eq("user_id", bag.user_id)
.maybeSingle();
const { data: itemsData, error: itemsErr } = await client
.from("items")
.select("*")
.eq("bag_id", bagId)
.order("added_at", { ascending: false });
if (itemsErr) return { error: itemsErr };
const { data: likeInfo } = await fetchLikeInfo(client, [bag.id], viewerId);
return {
data: {
id: bag.id,
name: bag.name,
ownerId: bag.user_id,
ownerName: (profile && profile.display_name) || "a friend",
likeCount: (likeInfo && likeInfo.counts[bag.id]) || 0,
isLiked: !!(likeInfo && likeInfo.likedSet.has(bag.id)),
items: (itemsData || []).map((item) => ({
id: item.id,
title: item.title,
price: item.price,
originalPrice: item.original_price,
size: item.size,
site: item.site,
image: item.image,
url: item.url,
addedAt: item.added_at
}))
}
};
}
async function loadBagEngagement(client, bagId) {
const { data: followsData, error: followsErr } = await client
.from("bag_follows")
.select("follower_id, created_at")
.eq("bag_id", bagId)
.order("created_at", { ascending: false });
if (followsErr) return { error: followsErr };
const { data: likesData, error: likesErr } = await client
.from("bag_likes")
.select("user_id, created_at")
.eq("bag_id", bagId)
.order("created_at", { ascending: false });
if (likesErr) return { error: likesErr };
const userIds = new Set();
(followsData || []).forEach((f) => userIds.add(f.follower_id));
(likesData || []).forEach((l) => userIds.add(l.user_id));
const nameById = {};
if (userIds.size > 0) {
const { data: profilesData, error: profilesErr } = await client
.from("profiles")
.select("user_id, display_name")
.in("user_id", Array.from(userIds));
if (profilesErr) return { error: profilesErr };
(profilesData || []).forEach((p) => { nameById[p.user_id] = p.display_name; });
}
const followers = (followsData || []).map((f) => ({
userId: f.follower_id,
name: nameById[f.follower_id] || "Someone",
at: f.created_at
}));
const likers = (likesData || []).map((l) => ({
userId: l.user_id,
name: nameById[l.user_id] || "Someone",
at: l.created_at
}));
return { data: { followers, likers } };
}
