async function fetchLikeInfo(client, bagIds, viewerId) {
if (!bagIds || bagIds.length === 0) return { data: { counts: {}, likedSet: new Set() } };
const { data, error } = await client
.from("bag_likes")
.select("bag_id, user_id")
.in("bag_id", bagIds);
if (error) return { error };
const counts = {};
const likedSet = new Set();
(data || []).forEach((row) => {
counts[row.bag_id] = (counts[row.bag_id] || 0) + 1;
if (row.user_id === viewerId) likedSet.add(row.bag_id);
});
return { data: { counts, likedSet } };
}
